// Reusable compact log avoids exposing payload contents in operations screens.
function AuditLog({ rows }: { rows: string[] }) {
  return rows.length ? (
    <div className="operation-log">
      {rows.map((text, i) => (
        <p key={`${text}-${i}`}>
          <Check size={13} />
          {text}
        </p>
      ))}
    </div>
  ) : (
    <EmptyState
      title="等待场景操作"
      description="进行状态变更或运行预演后，此处显示不含原文的操作记录。"
    />
  );
}
function PlusIcon() {
  return <span className="quality-plus">+</span>;
}
function RadioIcon() {
  return <Network size={26} />;
}
